        priority: 'HIGH',
        visual_brief: null,
        reel_bytes_script: "नमस्ते, मैं [Student Name] हूँ और मैं currently Prerna Commerce College में अपनी पढ़ाई कर रही हूँ।\n\nआज मैं आपसे अपने कॉलेज के experience के बारे में बताना चाहती हूँ।\n\nPrerna Commerce College में मुझे सिर्फ academics पर ही नहीं, बल्कि practical learning, communication skills और career development पर भी focus करने का मौका मिलता है।\n\nयहाँ के teachers और mentors हमें सही guidance देते हैं और हमारे future career के लिए prepare करते हैं।\n\nकॉलेज में होने वाली activities, learning और guidance ने मेरा confidence बढ़ाने में काफी मदद की है।\n\nअगर आप भी Commerce में अपना career बनाना चाहते हैं, तो Prerna Commerce College आपके लिए एक बेहतरीन choice हो सकता है।\n\nसीखते रहिए, आगे बढ़ते रहिए और अपने future के लिए हमेशा best देने की कोशिश कीजिए।\n\nThank you!",
