        format: 'CAROUSEL',
        post_category: 'REGULAR',
        priority: 'NORMAL',
        visual_brief: null,
        reel_bytes_script: null,
        caption: "Slide 1 — Why Do We Choose Our College?\n\nWhy do we choose our college?\nBecause for us, college is not just a place to study.\nIt is a place where we learn to become who we want to be.\n\nSlide 2 — Classroom\n\nOur classroom never feels like a typical classroom.\nIt feels like our comfort zone — where we learn not only from our books, but also about the world around us.\n\nSlide 3 — Computer Lab\n\nHere, we don’t just learn what is written in books.\nWe learn with hope, practical skills and experiences that prepare us for the future.\n\nSlide 4 — Teachers\n\nOur teachers don’t just teach us. They become our guides and partners.\nThey help us understand the difference between right and wrong — something no book can teach us completely.\n\nSlide 5 — Practical Lab\n\nHere, every practical feels like a chance to discover something new.\nWe learn by doing, experimenting and exploring — as if every day brings a new discovery.\n\nSlide 6 — Library\n\nOur library gives us more than just books.\nIt gives us knowledge, ideas and understanding that goes beyond the pages.\n\nSlide 7 — Final\n\nAnd that’s why we choose our college.\n\nThat’s why we choose Prerna College. ❤️\n\nBecause here, learning goes beyond books, classrooms and marks.",
