        visual_brief: "When I came here, I didn't know how to hold a pencil. I didn't know how to wait for my turn. I didn't know how to say I can. But someone showed me. How to say I care? But someone showed me. They smiled when I tried. They waited when I fell. And now, I am ready to take the next step. This is not goodbye. This is my beginning. (optional )",
