        content_pillar: "General",
        format: 'REEL',
        post_category: 'REGULAR',
        priority: 'HIGH',
        visual_brief: "EPISODE 1 — What Lies Beneath Us?\n\nStudent 1:\n“Hey, what are you thinking about?”\n\nStudent 2:\n“I was just wondering… we live on the surface of the Earth, but what’s actually underneath us? Could there be another world down there, just like ours?”\n\nStudent 1:\n“Not exactly a new world… but there are the Crust, Mantle, and Core.”\n\nStudent 2:\n“Crust, Mantle, Core… what are those? 😯”\n\nStudent 1:\n“They’re the different layers inside the Earth.”\n\nStudent 2:\n“Okay… but what exactly is inside these layers?”\n\nStudent 1:\n“We know quite a lot about them… but there’s something interesting.”\n\nStudent 2:\n“What?”\n\nStudent 1:\n“Everything inside the Earth isn’t completely still.”\n\nStudent 2:\n“Wait… you mean there’s movement happening beneath the ground?”\n\nStudent 1:\n“Exactly. And that movement is connected to… earthquakes.”\n\nStudent 2:\n“Seriously? Then how do earthquakes actually happen?”\n\nStudent 1:\n“To understand that, first we need to know how the Earth’s layers and tectonic plates work…”\n\nON SCREEN:\n“So, what’s really happening beneath our feet? 🌍”\nEPISODE 2",
        reel_bytes_script: "EPISODE 1 — What Lies Beneath Us?",
        caption: null,
