        post_category: 'REGULAR',
        priority: 'MEDIUM',
        visual_brief: "EPISODE 2 — How Does the Earth Move?\n\nStudent 1:\n“Yesterday, we were talking about the layers of the Earth… and you asked how there could be movement inside the Earth.”\n\nStudent 2:\n“Yeah, that’s what I want to understand. The ground feels completely stable to us… so how does it actually move?”\n\nStudent 1:\n“Actually, the Earth's outer solid layer isn’t one single piece. It’s divided into huge sections called tectonic plates.”\n\nStudent 2:\n“So, the ground we stand on is actually part of a plate?”\n\nStudent 1:\n“Exactly.”\n\nStudent 2:\n“But if these plates are moving, why don’t we feel it?”\n\nStudent 1:\n“Because their movement is extremely slow — usually just a few centimetres every year.”\n\nStudent 2:\n“Only a few centimetres? Then how can such slow movement cause an earthquake?”\n\nStudent 1:\n“That’s the interesting part. As the plates move, stress can build up along their boundaries.”\n\nStudent 2:\n“And when that stress becomes too much?”\n\nStudent 1:\n“The rocks can suddenly slip… releasing the energy that was stored.”\n\nStudent 2:\n“Wait… so that released energy is what causes an earthquake?”\n\nStudent 1:\n“Exactly.”\n\nStudent 2:\n“But when an earthquake happens, how does that energy actually make the ground shake?”\n\nStudent 1:\n“That’s what we’ll find out… in Episode 3.”\n\nON SCREEN:\n“How does an earthquake actually shake the ground? 🌍”\nEPISODE 3",
        reel_bytes_script: "EPISODE 2 — How Does the Earth Move?",
        caption: null,
